1	/**
2	 * AG UI event reducer and ChatView API for streaming chat transcripts.
3	 * Framework-free; attaches window.ChatView / globalThis.ChatView.
4	 */
5	(function () {
6	  "use strict";
7	
8	  function CreateChatState() {
9	    return {
10	      messages: new Map(),
11	      messageOrder: [],
12	      openTextMessages: new Set(),
13	      openToolCalls: new Map(),
14	      openReasoning: new Set(),
15	      runs: new Map(),
16	      activeSteps: new Map(),
17	      caughtUp: false,
18	      eventCount: 0,
19	      status: { kind: "loading", message: null },
20	    };
21	  }
22	
23	  function SynthesizeId(state, eventType) {
24	    return `${eventType}:${state.eventCount}`;
25	  }
26	
27	  function CreateChatMessage(id, role, options) {
28	    const opts = options || {};
29	    return {
30	      id: id,
31	      role: role,
32	      content: opts.content != null ? String(opts.content) : "",
33	      toolCalls: opts.toolCalls ? opts.toolCalls.slice() : [],
34	      toolCallId: opts.toolCallId != null ? opts.toolCallId : null,
35	      isStreaming: opts.isStreaming === true,
36	      timestamp: opts.timestamp != null ? opts.timestamp : null,
37	      activityType: opts.activityType != null ? opts.activityType : null,
38	    };
39	  }
40	
41	  function AddMessage(state, message) {
42	    if (!state.messages.has(message.id)) {
43	      state.messageOrder.push(message.id);
44	    }
45	    state.messages.set(message.id, message);
46	    return message;
47	  }
48	
49	  function AppendSystemMessage(state, content, id) {
50	    const messageId = id || SynthesizeId(state, "system");
51	    return AddMessage(
52	      state,
53	      CreateChatMessage(messageId, "system", { content: content })
54	    );
55	  }
56	
57	  function FindToolCallInfo(state, toolCallId) {
58	    for (const messageId of state.messageOrder) {
59	      const message = state.messages.get(messageId);
60	      if (!message || message.role !== "assistant") {
61	        continue;
62	      }
63	      for (const toolCall of message.toolCalls) {
64	        if (toolCall.id === toolCallId) {
65	          return toolCall;
66	        }
67	      }
68	    }
69	    return null;
70	  }
71	
72	  function RecomputeStatus(state) {
73	    if (state.status.kind === "error") {
74	      return;
75	    }
76	    if (!state.caughtUp) {
77	      state.status = { kind: "loading", message: null };
78	      return;
79	    }
80	    let hasRunning = false;
81	    for (const run of state.runs.values()) {
82	      if (run.status === "running") {
83	        hasRunning = true;
84	        break;
85	      }
86	    }
87	    if (hasRunning) {
88	      state.status = { kind: "live", message: null };
89	    } else {
90	      state.status = { kind: "complete", message: null };
91	    }
92	  }
93	
94	  function CloseOpenStreams(state) {
95	    for (const messageId of Array.from(state.openTextMessages)) {
96	      const message = state.messages.get(messageId);
97	      if (message) {
98	        message.isStreaming = false;
99	      }
100	      state.openTextMessages.delete(messageId);
101	    }
102	
103	    for (const toolCallId of Array.from(state.openToolCalls.keys())) {
104	      const openTool = state.openToolCalls.get(toolCallId);
105	      const toolInfo = FindToolCallInfo(state, toolCallId);
106	      if (toolInfo) {
107	        toolInfo.isOpen = false;
108	      }
109	      state.openToolCalls.delete(toolCallId);
110	      if (openTool) {
111	        openTool.argsBuffer = toolInfo ? toolInfo.args : openTool.argsBuffer;
112	      }
113	    }
114	
115	    for (const messageId of Array.from(state.openReasoning)) {
116	      const message = state.messages.get(messageId);
117	      if (message) {
118	        message.isStreaming = false;
119	      }
120	      state.openReasoning.delete(messageId);
121	    }
122	  }
123	
124	  function SnapshotMessageToChatMessage(snapshotMessage) {
125	    const role = snapshotMessage.role || "activity";
126	    const message = CreateChatMessage(String(snapshotMessage.id), role, {
127	      content:
128	        snapshotMessage.content != null ? String(snapshotMessage.content) : "",
129	      timestamp: snapshotMessage.timestamp != null ? snapshotMessage.timestamp : null,
130	      activityType:
131	        snapshotMessage.activityType != null
132	          ? snapshotMessage.activityType
133	          : null,
134	      toolCallId:
135	        snapshotMessage.toolCallId != null ? snapshotMessage.toolCallId : null,
136	    });
137	
138	    if (Array.isArray(snapshotMessage.toolCalls)) {
139	      message.toolCalls = snapshotMessage.toolCalls.map(function (toolCall) {
140	        return {
141	          id: String(toolCall.id || toolCall.toolCallId || ""),
142	          name: String(toolCall.name || toolCall.toolCallName || ""),
143	          args: toolCall.arguments != null ? String(toolCall.arguments) : toolCall.args != null ? String(toolCall.args) : "",
144	          result: toolCall.result != null ? String(toolCall.result) : null,
145	          isOpen: false,
146	        };
147	      });
148	    }
149	
150	    return message;
151	  }
152	
153	  function ParseActivityContent(message) {
154	    if (!message || !message.content) {
155	      return {};
156	    }
157	    try {
158	      const parsed = JSON.parse(message.content);
159	      if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
160	        return parsed;
161	      }
162	    } catch (_error) {
163	      //
164	    }
165	    return { text: message.content };
166	  }
167	
168	  function StringifyActivityContent(value) {
169	    if (typeof value === "string") {
170	      return value;
171	    }
172	    try {
173	      return JSON.stringify(value);
174	    } catch (_error) {
175	      return String(value);
176	    }
177	  }
178	
179	  function DecodeJsonPointerSegment(segment) {
180	    return segment.replace(/~1/g, "/").replace(/~0/g, "~");
181	  }
182	
183	  function ParseJsonPointer(path) {
184	    if (typeof path !== "string" || path === "" || path === "/") {
185	      return [];
186	    }
187	    if (path.charAt(0) !== "/") {
188	      return null;
189	    }
190	    return path
191	      .slice(1)
192	      .split("/")
193	      .map(DecodeJsonPointerSegment);
194	  }
195	
196	  function ResolvePatchParent(root, tokens) {
197	    if (!tokens || tokens.length === 0) {
198	      return { parent: null, key: null, valid: false };
199	    }
200	    let current = root;
201	    for (let index = 0; index < tokens.length - 1; index += 1) {
202	      const token = tokens[index];
203	      if (current == null || typeof current !== "object") {
204	        return { parent: null, key: null, valid: false };
205	      }
206	      current = current[token];
207	    }
208	    const lastToken = tokens[tokens.length - 1];
209	    if (current == null || typeof current !== "object") {
210	      return { parent: null, key: null, valid: false };
211	    }
212	    return { parent: current, key: lastToken, valid: true };
213	  }
214	
215	  function ApplyJsonPatch(document, patch) {
216	    if (!Array.isArray(patch)) {
217	      return null;
218	    }
219	
220	    let nextDocument;
221	    try {
222	      nextDocument = JSON.parse(JSON.stringify(document));
223	    } catch (_error) {
224	      return null;
225	    }
226	
227	    for (const operation of patch) {
228	      if (!operation || typeof operation !== "object") {
229	        return null;
230	      }
231	
232	      const op = operation.op;
233	      const pathTokens = ParseJsonPointer(operation.path);
234	      if (pathTokens === null) {
235	        return null;
236	      }
237	
238	      if (op === "add" || op === "replace") {
239	        if (pathTokens.length === 0) {
240	          if (op === "replace") {
241	            nextDocument = operation.value;
242	          } else {
243	            return null;
244	          }
245	          continue;
246	        }
247	
248	        const resolved = ResolvePatchParent(nextDocument, pathTokens);
249	        if (!resolved.valid) {
250	          return null;
251	        }
252	
253	        if (Array.isArray(resolved.parent) && resolved.key === "-") {
254	          if (op !== "add") {
255	            return null;
256	          }
257	          resolved.parent.push(operation.value);
258	        } else {
259	          resolved.parent[resolved.key] = operation.value;
260	        }
261	      } else if (op === "remove") {
262	        if (pathTokens.length === 0) {
263	          return null;
264	        }
265	        const resolved = ResolvePatchParent(nextDocument, pathTokens);
266	        if (!resolved.valid) {
267	          return null;
268	        }
269	        if (Array.isArray(resolved.parent)) {
270	          const index = Number(resolved.key);
271	          if (!Number.isInteger(index) || index < 0 || index >= resolved.parent.length) {
272	            return null;
273	          }
274	          resolved.parent.splice(index, 1);
275	        } else {
276	          delete resolved.parent[resolved.key];
277	        }
278	      } else {
279	        return null;
280	      }
281	    }
282	
283	    return nextDocument;
284	  }
285	
286	  function CustomDisplayText(event) {
287	    if (event.name === "provider.text") {
288	      const value = event.value;
289	      if (value && typeof value === "object") {
290	        if (value.text != null) {
291	          return String(value.text);
292	        }
293	      }
294	      if (event.text != null) {
295	        return String(event.text);
296	      }
297	      return "";
298	    }
299	    return String(event.name || "custom");
300	  }
301	
302	  function ReduceAguiEvent(state, event) {
303	    if (!event || typeof event !== "object") {
304	      return state;
305	    }
306	
307	    state.eventCount += 1;
308	    const eventType = event.type;
309	
310	    switch (eventType) {
311	      case "RUN_STARTED": {
312	        const runId = event.runId ? String(event.runId) : SynthesizeId(state, "RUN_STARTED");
313	        state.runs.set(runId, {
314	          runId: runId,
315	          threadId: event.threadId != null ? String(event.threadId) : runId,
316	          status: "running",
317	        });
318	        RecomputeStatus(state);
319	        break;
320	      }
321	
322	      case "RUN_FINISHED": {
323	        const runId = event.runId ? String(event.runId) : null;
324	        if (runId && state.runs.has(runId)) {
325	          const run = state.runs.get(runId);
326	          run.status = "finished";
327	        }
328	        CloseOpenStreams(state);
329	        RecomputeStatus(state);
330	        break;
331	      }
332	
333	      case "RUN_ERROR": {
334	        const runId = event.runId ? String(event.runId) : null;
335	        if (runId && state.runs.has(runId)) {
336	          const run = state.runs.get(runId);
337	          run.status = "error";
338	        }
339	        const errorText = event.message != null ? String(event.message) : "Run error";
340	        AppendSystemMessage(
341	          state,
342	          errorText,
343	          runId ? `error:${runId}` : SynthesizeId(state, "RUN_ERROR")
344	        );
345	        state.status = { kind: "error", message: errorText };
346	        break;
347	      }
348	
349	      case "STEP_STARTED": {
350	        const stepName = event.stepName ? String(event.stepName) : SynthesizeId(state, "STEP_STARTED");
351	        state.activeSteps.set(stepName, {
352	          stepName: stepName,
353	          startTimestamp: event.timestamp != null ? event.timestamp : null,
354	        });
355	        break;
356	      }
357	
358	      case "STEP_FINISHED": {
359	        const stepName = event.stepName ? String(event.stepName) : null;
360	        if (stepName) {
361	          state.activeSteps.delete(stepName);
362	        }
363	        break;
364	      }
365	
366	      case "TEXT_MESSAGE_START": {
367	        const messageId = event.messageId
368	          ? String(event.messageId)
369	          : SynthesizeId(state, "TEXT_MESSAGE_START");
370	        const role = event.role ? String(event.role) : "assistant";
371	        AddMessage(
372	          state,
373	          CreateChatMessage(messageId, role, {
374	            isStreaming: true,
375	            timestamp: event.timestamp != null ? event.timestamp : null,
376	          })
377	        );
378	        state.openTextMessages.add(messageId);
379	        break;
380	      }
381	
382	      case "TEXT_MESSAGE_CONTENT": {
383	        const messageId = event.messageId ? String(event.messageId) : null;
384	        if (!messageId) {
385	          break;
386	        }
387	        let message = state.messages.get(messageId);
388	        if (!message) {
389	          message = AddMessage(
390	            state,
391	            CreateChatMessage(messageId, "assistant", { isStreaming: true })
392	          );
393	          state.openTextMessages.add(messageId);
394	        }
395	        message.content += event.delta != null ? String(event.delta) : "";
396	        break;
397	      }
398	
399	      case "TEXT_MESSAGE_END": {
400	        const messageId = event.messageId ? String(event.messageId) : null;
401	        if (!messageId) {
402	          break;
403	        }
404	        const message = state.messages.get(messageId);
405	        if (message) {
406	          message.isStreaming = false;
407	        }
408	        state.openTextMessages.delete(messageId);
409	        break;
410	      }
411	
412	      case "TOOL_CALL_START": {
413	        const toolCallId = event.toolCallId
414	          ? String(event.toolCallId)
415	          : SynthesizeId(state, "TOOL_CALL_START");
416	        const toolCallName = event.toolCallName
417	          ? String(event.toolCallName)
418	          : "tool";
419	        const parentMessageId = event.parentMessageId
420	          ? String(event.parentMessageId)
421	          : null;
422	
423	        state.openToolCalls.set(toolCallId, {
424	          toolCallId: toolCallId,
425	          toolCallName: toolCallName,
426	          argsBuffer: "",
427	          parentMessageId: parentMessageId,
428	        });
429	
430	        if (parentMessageId && state.messages.has(parentMessageId)) {
431	          const parent = state.messages.get(parentMessageId);
432	          if (parent.role === "assistant") {
433	            parent.toolCalls.push({
434	              id: toolCallId,
435	              name: toolCallName,
436	              args: "",
437	              result: null,
438	              isOpen: true,
439	            });
440	          }
441	        }
442	        break;
443	      }
444	
445	      case "TOOL_CALL_ARGS": {
446	        const toolCallId = event.toolCallId ? String(event.toolCallId) : null;
447	        if (!toolCallId) {
448	          break;
449	        }
450	        const delta = event.delta != null ? String(event.delta) : "";
451	        const openTool = state.openToolCalls.get(toolCallId);
452	        if (openTool) {
453	          openTool.argsBuffer += delta;
454	        }
455	        const toolInfo = FindToolCallInfo(state, toolCallId);
456	        if (toolInfo) {
457	          toolInfo.args += delta;
458	        }
459	        break;
460	      }
461	
462	      case "TOOL_CALL_END": {
463	        const toolCallId = event.toolCallId ? String(event.toolCallId) : null;
464	        if (!toolCallId) {
465	          break;
466	        }
467	        const toolInfo = FindToolCallInfo(state, toolCallId);
468	        if (toolInfo) {
469	          toolInfo.isOpen = false;
470	        }
471	        state.openToolCalls.delete(toolCallId);
472	        break;
473	      }
474	
475	      case "TOOL_CALL_RESULT": {
476	        const toolCallId = event.toolCallId ? String(event.toolCallId) : null;
477	        const messageId = event.messageId
478	          ? String(event.messageId)
479	          : toolCallId
480	            ? `${toolCallId}:result`
481	            : SynthesizeId(state, "TOOL_CALL_RESULT");
482	        const content =
483	          event.content != null
484	            ? typeof event.content === "string"
485	              ? event.content
486	              : JSON.stringify(event.content)
487	            : "";
488	
489	        AddMessage(
490	          state,
491	          CreateChatMessage(messageId, "tool", {
492	            content: content,
493	            toolCallId: toolCallId,
494	            timestamp: event.timestamp != null ? event.timestamp : null,
495	          })
496	        );
497	
498	        if (toolCallId) {
499	          const toolInfo = FindToolCallInfo(state, toolCallId);
500	          if (toolInfo) {
501	            toolInfo.result = content;
502	          }
503	        }
504	        break;
505	      }
506	
507	      case "REASONING_START":
508	        break;
509	
510	      case "REASONING_MESSAGE_START": {
511	        const messageId = event.messageId
512	          ? String(event.messageId)
513	          : SynthesizeId(state, "REASONING_MESSAGE_START");
514	        AddMessage(
515	          state,
516	          CreateChatMessage(messageId, "reasoning", {
517	            isStreaming: true,
518	            timestamp: event.timestamp != null ? event.timestamp : null,
519	          })
520	        );
521	        state.openReasoning.add(messageId);
522	        break;
523	      }
524	
525	      case "REASONING_MESSAGE_CONTENT": {
526	        const messageId = event.messageId ? String(event.messageId) : null;
527	        if (!messageId) {
528	          break;
529	        }
530	        let message = state.messages.get(messageId);
531	        if (!message) {
532	          message = AddMessage(
533	            state,
534	            CreateChatMessage(messageId, "reasoning", { isStreaming: true })
535	          );
536	          state.openReasoning.add(messageId);
537	        }
538	        message.content += event.delta != null ? String(event.delta) : "";
539	        break;
540	      }
541	
542	      case "REASONING_MESSAGE_END": {
543	        const messageId = event.messageId ? String(event.messageId) : null;
544	        if (!messageId) {
545	          break;
546	        }
547	        const message = state.messages.get(messageId);
548	        if (message) {
549	          message.isStreaming = false;
550	        }
551	        state.openReasoning.delete(messageId);
552	        break;
553	      }
554	
555	      case "REASONING_END": {
556	        const messageId = event.messageId ? String(event.messageId) : null;
557	        if (messageId) {
558	          const message = state.messages.get(messageId);
559	          if (message) {
560	            message.isStreaming = false;
561	          }
562	          state.openReasoning.delete(messageId);
563	        } else {
564	          for (const openId of Array.from(state.openReasoning)) {
565	            const message = state.messages.get(openId);
566	            if (message) {
567	              message.isStreaming = false;
568	            }
569	          }
570	          state.openReasoning.clear();
571	        }
572	        break;
573	      }
574	
575	      case "REASONING_ENCRYPTED_VALUE":
576	        break;
577	
578	      case "CUSTOM": {
579	        const messageId = event.messageId
580	          ? String(event.messageId)
581	          : SynthesizeId(state, "CUSTOM");
582	        const displayText = CustomDisplayText(event);
583	        AddMessage(
584	          state,
585	          CreateChatMessage(messageId, "activity", {
586	            content: displayText,
587	            activityType: event.name ? String(event.name) : "custom",
588	            timestamp: event.timestamp != null ? event.timestamp : null,
589	          })
590	        );
591	        break;
592	      }
593	
594	      case "RAW": {
595	        const messageId = event.messageId
596	          ? String(event.messageId)
597	          : SynthesizeId(state, "RAW");
598	        AddMessage(
599	          state,
600	          CreateChatMessage(messageId, "activity", {
601	            content: "unrecognized event",
602	            activityType: event.source ? String(event.source) : "raw",
603	            timestamp: event.timestamp != null ? event.timestamp : null,
604	          })
605	        );
606	        break;
607	      }
608	
609	      case "ACTIVITY_SNAPSHOT": {
610	        const messageId = event.messageId
611	          ? String(event.messageId)
612	          : SynthesizeId(state, "ACTIVITY_SNAPSHOT");
613	        const contentValue = event.content != null ? event.content : {};
614	        AddMessage(
615	          state,
616	          CreateChatMessage(messageId, "activity", {
617	            content: StringifyActivityContent(contentValue),
618	            activityType: event.activityType
619	              ? String(event.activityType)
620	              : "activity",
621	            timestamp: event.timestamp != null ? event.timestamp : null,
622	          })
623	        );
624	        break;
625	      }
626	
627	      case "ACTIVITY_DELTA": {
628	        const messageId = event.messageId ? String(event.messageId) : null;
629	        if (!messageId) {
630	          break;
631	        }
632	        const message = state.messages.get(messageId);
633	        if (!message || message.role !== "activity") {
634	          break;
635	        }
636	        const currentContent = ParseActivityContent(message);
637	        const patched = ApplyJsonPatch(currentContent, event.patch);
638	        if (patched !== null) {
639	          message.content = StringifyActivityContent(patched);
640	        }
641	        if (event.activityType) {
642	          message.activityType = String(event.activityType);
643	        }
644	        break;
645	      }
646	
647	      case "MESSAGES_SNAPSHOT": {
648	        state.messages.clear();
649	        state.messageOrder = [];
650	        state.openTextMessages.clear();
651	        state.openToolCalls.clear();
652	        state.openReasoning.clear();
653	
654	        const snapshotMessages = Array.isArray(event.messages) ? event.messages : [];
655	        for (const snapshotMessage of snapshotMessages) {
656	          if (!snapshotMessage || snapshotMessage.id == null) {
657	            continue;
658	          }
659	          AddMessage(state, SnapshotMessageToChatMessage(snapshotMessage));
660	        }
661	        break;
662	      }
663	
664	      case "STATE_SNAPSHOT":
665	      case "STATE_DELTA":
666	        break;
667	
668	      default:
669	        break;
670	    }
671	
672	    return state;
673	  }
674	
675	  function ApplyServerMessage(state, message) {
676	    if (!message || typeof message !== "object") {
677	      return state;
678	    }
679	
680	    const messageType = message.type;
681	    if (messageType === "events") {
682	      const events = Array.isArray(message.events) ? message.events : [];
683	      for (const event of events) {
684	        ReduceAguiEvent(state, event);
685	      }
686	      return state;
687	    }
688	
689	    if (messageType === "caught_up") {
690	      state.caughtUp = true;
691	      RecomputeStatus(state);
692	      return state;
693	    }
694	
695	    if (messageType === "error") {
696	      const errorText =
697	        message.message != null ? String(message.message) : "Connection error";
698	      AppendSystemMessage(state, errorText, SynthesizeId(state, "server_error"));
699	      state.status = { kind: "error", message: errorText };
700	      return state;
701	    }
702	
703	    return state;
704	  }
705	
706	  function RenderMinimal(container, state) {
707	    if (!container) {
708	      return;
709	    }
710	    const statusText = state.status.message || state.status.kind;
711	    const eventCount = state.eventCount;
712	    const messageCount = state.messageOrder.length;
713	    container.textContent = `status=${statusText} events=${eventCount} messages=${messageCount}`;
714	  }
715	
716	  function Create(container, wsUrl) {
717	    const state = CreateChatState();
718	    const owned = {
719	      socket: null,
720	      reconnectTimer: null,
721	      listeners: [],
722	      destroyed: false,
723	    };
